 unsigned char r = 'l';
 unsigned char g = 'l';
 unsigned char b = 'l';

void drawColumn(int xscroll, int xpos, int topypos, int bottomypos, int height, char l, float shadow)
{
	height = height;
    const int texHeight = 64;
    int texColumnOffset = xscroll * 192;

    int yStart = (l == 'u') ? bottomypos : topypos;
    int yStep  = (l == 'u') ? 1 : -1;

    // Fixed-point texture stepping
    int texStep = (texHeight << 16) / (height);

    // ---------------------------------------------------------
    // 1. Compute how many pixels are clipped off the top
    // ---------------------------------------------------------
    int clipped = 0;

    if (l == 'u')
    {
        // bottom ? up
        if (yStart < 0)
            clipped = -yStart;
    }
    else
    {
        // top ? down
        if (yStart >= SCREEN_H)
            clipped = yStart - (SCREEN_H - 1);
    }

    if (clipped < 0) clipped = 0;
    if (clipped > height) clipped = height;

    // ---------------------------------------------------------
    // 2. Offset texture sampling by clipped amount
    // ---------------------------------------------------------
    int v = clipped * texStep;

    // ---------------------------------------------------------
    // 3. Move yStart to the first visible pixel
    // ---------------------------------------------------------
    yStart += clipped * yStep;

    // ---------------------------------------------------------
    // 4. Draw only the visible portion
    // ---------------------------------------------------------
    for (int d = clipped; d < height; d++)
    {
        int y = yStart + (d - clipped) * yStep;

        if (y < 0 || y >= SCREEN_H)
            continue;

        int i0 = (v >> 16);
        int base = texColumnOffset + (i0 * 3);
        
		if(l == 'l'){
         r = doorRGB[base];
         g = doorRGB[base + 1];
         b = doorRGB[base + 2];
		}
		if(l == 'd'){
         r = ((doorRGB[base]));// * lightmap;
         g = ((doorRGB[base + 1]));// * lightmap;
         b = ((doorRGB[base + 2])) ;// * lightmap;
		}
		
		
		
        uint32_t color = (0xFFu << 24) | (r << 16) | (g << 8) | b;

        uint32_t *row = &framebuffer[y * SCREEN_W + xpos];
		row[0] = color;
        row[1] = color;
        row[2] = color;

        v += texStep;
    }
}



