inline float cross2(float ax,float ay,float bx,float by)
{
    return ax*by - ay*bx; 
}




bool ray_segment_intersect_fast(
    float rx, float ry,          // ray start
    float ex, float ey,          // ray END (your scanProgression, linescanDistance)
    float x1, float y1,          // segment start
    float x2, float y2,          // segment end
    float &out_ix, float &out_iy // OUTPUT: intersection X,Y
)
{
    // Ray direction from start to end
    float rdx = ex - rx;
    float rdy = ey - ry;

    // Segment direction
    float sx = x2 - x1;
    float sy = y2 - y1;

    // Vector from ray origin to segment start
    float qpx = x1 - rx;
    float qpy = y1 - ry;

    float den = cross2(rdx, rdy, sx, sy);
    const float EPS = 1e-8f;
    if (fabs(den) < EPS) return false; // parallel

    float t = cross2(qpx, qpy, sx, sy) / den;
    float u = cross2(qpx, qpy, rdx, rdy) / den;

    // Check intersection ranges
    if (t < 0.0f) return false;   // behind ray start
    if (u < 0.0f || u > 1.0f) return false; // outside segment

    // Compute intersection point
    out_ix = rx + rdx * t;
    out_iy = ry + rdy * t;

    return true;
}



