void move(int xdir, int ydir)
{
	int m = 0;
	//update this to size of point array!
	for(m = 0; m < (sizeof(xpoint)/sizeof(int)); m++)
	{
		xpoint[m] += xdir;  
		ypoint[m] += ydir;
	}
	
}











